#!/usr/bin/env node
// Writes usage-spend-vectors.json: cases for usageSpend (DEC-0110, the contract's src/usage-rules.ts), each answered by
// the contract's own function at the pin, never written by hand. The kits' usage_spend / usageSpend are held to them,
// and the budget's spentUsd counts the money they answer (CT-115). The contract ships no vector file for usageSpend: the
// cases are its own test's (test/usage-rules.test.ts) and hostile ones of this kit.
//
//   node test/fixtures/contract/make_usage_spend_vectors.mjs --contract-src <dir with its src/*.ts staged, .js imports
//     rewritten to .ts> [--out test/fixtures/contract/usage-spend-vectors.json]
//
// Needs Node 24 or later (type stripping).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const args = Object.fromEntries(process.argv.slice(2).reduce((acc, a, i, all) => (a.startsWith('--') ? [...acc, [a.slice(2), all[i + 1]]] : acc), []));
const here = path.dirname(fileURLToPath(import.meta.url));
const usage = await import(pathToFileURL(path.join(args['contract-src'], 'usage-rules.ts')).href);
const row = (route, calls, costUsd, unpricedCalls = 0) => ({ provider: 'p', model: 'm', ...(route ? { route } : {}), calls, unpricedCalls, costUsd });

const inputs = [
  ['the finding of 2026-10-22', [row('subscription', 300, 140.47), row('key', 40, 4.8), row('platform-metered', 2, 1), row(undefined, 1, 1)]],
  ['only a subscription', [row('subscription', 5, 2)]],
  ['no rows', []],
  ['unpriced key beside a subscription', [row('key', 3, null, 3), row('subscription', 1, 0.5)]],
  ['key partly priced', [row('key', 3, null, 3), row('key', 2, 1.25, 1)]],
  ['unpriced subscription', [row('subscription', 3, null, 3)]],
  ['subscription partly priced', [row('subscription', 3, 1, 1)]],
  ['an unknown route', [row('free', 1, 1)]],
  ['a null route', [{ ...row('key', 1, 1), route: null }]],
  ['negative calls', [row('key', -1, 1)]],
  ['fractional calls', [row('key', 1.5, 1)]],
  ['a negative cost', [row('key', 1, -1)]],
  ['more unpriced than calls', [row('key', 2, 1, 3)]],
  ['a null cost with a priced call', [row('key', 2, null, 1)]],
  ['a cost with every call unpriced', [row('key', 2, 1, 2)]],
  ['a null row', [null]],
  ['a number row', [7]],
  ['a string row', ['row']],
  ['an array row', [[row('key', 1, 1)]]],
  ['calls with its own toString', [{ ...row('key', 1, 1), calls: { toString: 1 } }]],
  ['calls as a string', [{ ...row('key', 1, 1), calls: '1' }]],
  ['calls as true', [{ ...row('key', 1, 1), calls: true }]],
  ['a cost as a string', [{ ...row('key', 1, 1), costUsd: '1' }]],
  ['a cost as true', [{ ...row('key', 1, 1), costUsd: true }]],
  ['no rows array: null', null],
  ['no rows array: an object', {}],
  ['no rows array: a string', 'rows'],
  ['no rows array: a length', { length: 1 }],
  ['a key row without calls and no price', [row('key', 0, null)]],
  ['a priced key row without calls beside unpriced calls', [row('key', 0, 0), row('key', 3, null, 3)]],
  ['a priced subscription row without calls beside unpriced calls', [row('subscription', 0, 0), row('subscription', 3, null, 3)]],
  ['a key row without calls that costs', [row('key', 0, 5)]],
  ['a costing row without calls beside a priced one', [row('key', 0, 5), row('key', 1, 1)]],
  ['unpricedCalls null', [{ ...row('key', 1, 1), unpricedCalls: null }]],
  ['no unpricedCalls member', [{ provider: 'p', model: 'm', route: 'key', calls: 2, costUsd: 0.5 }]],
  ['small costs in one order', [row('key', 1, 0.1), row('key', 1, 0.2), row('key', 1, 1e-7), row('key', 1, 3)]],
  ['small costs in the other order', [row('key', 1, 3), row('key', 1, 1e-7), row('key', 1, 0.2), row('key', 1, 0.1)]],
  ['many tenths', Array.from({ length: 10 }, () => row('key', 1, 0.1))],
  ['calls at 2^53 - 1', [row('key', 9007199254740991, 1)]],
  ['calls past 2^53', [row('key', 9007199254740992, 1)]],
  ['calls written 1.0', [row('key', 1.0, 1)]],
  ['a zero cost of -0', [row('key', 1, -0)]],
];
const cases = inputs.map(([name, rows]) => ({ name, rows, expected: usage.usageSpend(rows) ?? null }));
const out = args.out ?? path.join(here, 'usage-spend-vectors.json');
fs.writeFileSync(out, `${JSON.stringify({ $comment: 'Generated by make_usage_spend_vectors.mjs from the contract pin\'s src/usage-rules.ts usageSpend (DEC-0110); do not edit by hand.', cases }, null, 2)}\n`);
console.log(`wrote ${cases.length} usageSpend cases to ${out}`);
